PRAGMA foreign_keys = ON;

-- WorkforceIQ seed: departments, roles, and role_skills
-- Reconstructed from the finalized 16-role / 154-role-skill design.
-- Intended for a clean database after schema.sql and seed_skills.sql.




-- Validation
SELECT COUNT(*) AS total_departments FROM departments;
SELECT COUNT(*) AS total_roles FROM roles;
SELECT COUNT(*) AS total_role_skills FROM role_skills;

SELECT d.department_name, COUNT(r.role_id) AS role_count
FROM departments d
LEFT JOIN roles r ON r.department_id = d.department_id
GROUP BY d.department_id, d.department_name
ORDER BY d.department_name;

SELECT r.role_name, COUNT(rs.skill_id) AS skill_count
FROM roles r
LEFT JOIN role_skills rs ON rs.role_id = r.role_id
GROUP BY r.role_id, r.role_name
ORDER BY r.role_name;

PRAGMA foreign_key_check;